fn caesar_shift(s: String, k: Int) -> String {
  return s
    |> enumerate
    |> map(|(i, c)| match c {
      'a'..'z' => {
        let base = 'a' as u8;
        let shifted = ((c as u8 - base + k as u8) % 26 + base) as char;
        (i, shifted)
      },
      _ => (i, c),
    })
    |> sort_by(|(i1, _), (i2, _)| i1.cmp(i2))
    |> map(|(_, c)| c)
    |> join("")
}

