type Job {
  name: String,
  deps: List[String],
}

fn build_order(jobs: List[Job]) -> Result[List[String], String] {
  let job_map = jobs
    |> map(|j| (j.name, j.deps))
    |> map_from();

  let mut order = [];
  let mut placed = [];
  let mut remaining = jobs;

  while remaining.len() > 0 {
    let mut placed_this_round = false;
    for j in remaining {
      if j.deps
        |> filter(|d| !placed.contains(d))
        |> len() == 0
      {
        order.push(j.name);
        placed.push(j.name);
        placed_this_round = true;
        remaining = remaining
          |> filter(|r| r.name != j.name);
      }
    }
    if !placed_this_round {
      return Err("cycle detected".to_string());
    }
  }

  Ok(order)
}

