type Player {
  name: String,
  score: Int,
}

fn competition_rank(players: List[Player]) -> List[(Int, String)] {
  let sorted_players = players |> sort_by(|p| (-p.score, p.name));
  let mut ranks = Vec::new();
  let mut rank = 1;
  let mut prev_score = None;

  for player in sorted_players {
    match prev_score {
      Some(prev) if prev > player.score => {
        rank += 1;
      },
      _ => {}
    }
    ranks.push((rank, player.name));
    prev_score = Some(player.score);
  }

  return ranks;
}

