type Cell = (Int, Int)

fn is_valid(grid: List[String], cell: Cell) -> Bool {
  let (x, y) = cell
  x >= 0 && x < len(grid) && y >= 0 && y < str_len(grid[0])
}

fn is_land(grid: List[String], cell: Cell) -> Bool {
  let (x, y) = cell
  grid[x][y] == '#'
}

fn dfs(grid: List[String], cell: Cell, visited: List[List[Bool]]) -> Int {
  if !is_valid(grid, cell) || visited[cell.0][cell.1] || !is_land(grid, cell) {
    return 0
  }
  visited[cell.0][cell.1] = true
  let mut count = 1
  count = count + dfs(grid, (cell.0 - 1, cell.1), visited)
  count = count + dfs(grid, (cell.0 + 1, cell.1), visited)
  count = count + dfs(grid, (cell.0, cell.1 - 1), visited)
  count = count + dfs(grid, (cell.0, cell.1 + 1), visited)
  return count
}

fn count_islands(grid: List[String]) -> (Int, Int) {
  let rows = len(grid)
  if rows == 0 {
    return (0, 0)
  }
  let cols = str_len(grid[0])
  let mut visited = map_from(List[List[Bool]](rows, List[Bool](cols, false)))
  let mut island_count = 0
  let mut max_size = 0
  for i in range(0, rows) {
    for j in range(0, cols) {
      if !visited[i][j] && is_land(grid, (i, j)) {
        island_count = island_count + 1
        let size = dfs(grid, (i, j), visited)
        if size > max_size {
          max_size = size
        }
      }
    }
  }
  return (island_count, max_size)
}

