fn heading_numbers(lines: List[String]) -> List[String] {
  var counters = [0, 0, 0]
  var result = []

  for line in lines {
    if line.starts_with("#") && line.len() > 1 {
      let level = line.chars().take_while(|&c| c == '#').count()
      let title = line[level + 1..].trim().to_string()
      if level > 0 && level <= 3 {
        counters[0..level].iter_mut().for_each(|c| *c = 0)
        counters[level - 1] += 1
        result.push(format!("{}.{} {}{}", counters[0], counters[1], counters[2], title))
      }
    }
  }

  return result
}

