type ParseError {
  kind: String,
  pos: Int,
}

fn parse_int(s: String) -> Result[Int, ParseError] {
  match parse_int(s) {
    Some(i) => Ok(i),
    None => Err(ParseError { kind: "invalid integer", pos: 0 }),
  }
}

fn parse_element(s: String) -> Result[(Int, String), ParseError] {
  if str_len(s) == 0 {
    return Err(ParseError { kind: "unexpected end", pos: 0 });
  }
  if s[0] == '[' {
    let (list, rest) = parse_list(s[1..]);
    if rest[0] != ']' {
      return Err(ParseError { kind: "expected ']' after list", pos: 1 });
    }
    return Ok((list, rest[1..]));
  } else if s[0] == '-' || (s[0] >= '0' && s[0] <= '9') {
    let i = parse_int(s);
    return Ok((i, ""));
  } else {
    return Err(ParseError { kind: "unexpected character", pos: 0 });
  }
}

fn parse_list(s: String) -> (List[Int], String) {
  let mut result = List[Int]{};
  let mut depth = 0;
  let mut i = 0;
  while i < str_len(s) {
    if s[i] == ',' {
      i += 1;
    } else if s[i] == '[' {
      depth += 1;
      let (list, rest) = parse_list(s[i+1..]);
      result = append(result, list);
      i += str_len(rest) + 1;
    } else if s[i] == ']' {
      depth -= 1;
      return (result, s[i+1..]);
    } else if s[i] == '-' || (s[i] >= '0' && s[i] <= '9') {
      let (num, rest) = parse_element(s[i..]);
      result = append(result, List[Int]{ num });
      i += str_len(rest);
    } else {
      return (result, s[i..]);
    }
  }
  return (result, "");
}

fn flatten_nested(s: String) -> Result[(List[Int], Int), String] {
  let s = s |> replace(" ", "");
  let (result, rest) = parse_list(s);
  if str_len(rest) != 0 {
    return Err("invalid at " + to_string(str_len(s)));
  }
  return Ok((result, depth));
}

