fn parse_query(s: String) -> Result[List[(String, String)], String] {
  let items = s.split('&').filter(|i| i != "").map(|i| i.split_once('=')).collect::<List<Option<(String, String)>>>();
  let mut result = List[(String, String)]();
  for item in items {
    match item {
      Some((key, value)) => {
        let key = key.replace('+', " ");
        let value = value.replace('+', " ");
        if key == "" {
          return Err(format!("empty key: {}", item.unwrap_or("")));
        }
        result = result.append((key, value));
      },
      None => continue,
    }
  }
  return Ok(result);
}

