  M: Int,
}

fn roman_to_int(s: String) -> Result[Int, String] {
  let roman_map = map_from([
    ("M", 1000),
    ("CM", 900),
    ("D", 500),
    ("CD", 400),
    ("C", 100),
    ("XC", 90),
    ("L", 50),
    ("XL", 40),
    ("X", 10),
    ("IX", 9),
    ("V", 5),
    ("IV", 4),
    ("I", 1),
  ]);

  if str_len(s) == 0 {
    return Err("empty".to_string());
  }

  let mut result = 0;
  let mut i = 0;
  while i < str_len(s) {
    if i + 1 < str_len(s) && map_get(roman_map, s[i..i+2]) != None {
      result = result + map_get(roman_map, s[i..i+2]).unwrap();
      i = i + 2;
    } else {
      result = result + map_get(roman_map, s[i..i+1]).unwrap();
      i = i + 1;
    }
  }

  if result < 1 || result > 3999 {
    return Err("not canonical".to_string());
  }

  Ok(result)
}

