from __future__ import annotations
from typing import Callable, Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str

class Stock(TypedDict):
    sku: str
    qty: int

class Txn(TypedDict):
    sku: str
    delta: int

def inventory_ledger(stock: list[Stock], txns: list[Txn]) -> Ok[list[Stock]] | Err:
    stock_dict = {s['sku']: s['qty'] for s in stock}
    for i, txn in enumerate(txns, start=1):
        if txn['sku'] not in stock_dict:
            return Err(ok=False, error=f"txn {i}: unknown sku {txn['sku']}")
        if stock_dict[txn['sku']] + txn['delta'] < 0:
            return Err(ok=False, error=f"txn {i}: {txn['sku']} would go negative")
        stock_dict[txn['sku']] += txn['delta']
    final_stock = sorted((s for s in stock if stock_dict[s['sku']] > 0), key=lambda s: s['sku'])
    return Ok(ok=True, value=final_stock)

